import { getAttribute, getAttributeValue, getTagName } from "../jsx.mjs";

export default {
  meta: {
    type: "problem",
    docs: { description: "一覧の Table は契約で定義した variant を使う" },
    schema: [{ type: "object", properties: { variant: { type: "string" } }, additionalProperties: false }],
    messages: {
      mismatch: "検出variant: {{value}}(契約は {{expected}})",
      missing: "Table.Rootを確認できません",
    },
  },
  create(context) {
    const expected = context.options[0]?.variant ?? "primary";
    let roots = 0;
    return {
      JSXOpeningElement(node) {
        const tagName = getTagName(node.name);
        if (tagName !== "Table.Root" && tagName !== "Table") return;
        roots += 1;
        const value = getAttributeValue(getAttribute(node, "variant")) ?? "primary";
        if (value === expected) return;
        context.report({ node, messageId: "mismatch", data: { value: typeof value === "string" ? value : "動的指定", expected } });
      },
      "Program:exit"(node) {
        if (roots === 0) context.report({ node, messageId: "missing" });
      },
    };
  },
};
import { getAttributeValue, getBaseName } from "../jsx.mjs";

// 形式検証を求める項目は題材ごとに変わる（顧客のメール、請求書の支払期限）。
// type は example の lint.requiredInputType から渡す。メッセージにも出して、
// 別題材の画面に「メール形式」を求める文言が出ないようにする
export default {
  meta: {
    type: "problem",
    docs: { description: "形式検証が要る入力に想定の type を指定する" },
    schema: [
      {
        type: "object",
        properties: { type: { type: "string", minLength: 1 } },
        required: ["type"],
        additionalProperties: false,
      },
    ],
    messages: { missing: "type={{type}} の入力制御を確認できません" },
  },
  create(context) {
    const expectedType = context.options[0].type;
    let hasField = false;
    let hasExpectedType = false;
    return {
      JSXOpeningElement(node) {
        const base = getBaseName(node.name);
        if (base === "Input" || base === "TextField") hasField = true;
      },
      JSXAttribute(node) {
        if (node.name.type === "JSXIdentifier" && node.name.name === "type" && getAttributeValue(node) === expectedType) {
          hasExpectedType = true;
        }
      },
      "Program:exit"(node) {
        if (!(hasField && hasExpectedType)) context.report({ node, messageId: "missing", data: { type: expectedType } });
      },
    };
  },
};
import { getTagName } from "../jsx.mjs";

export default {
  meta: {
    type: "problem",
    docs: { description: "入力に視覚ラベルまたは aria-label を付ける" },
    schema: [],
    messages: { missing: "入力ラベルを確認できません" },
  },
  create(context) {
    let hasLabel = false;
    return {
      JSXOpeningElement(node) {
        if (/^(?:label|Label)(?:\.|$)/.test(getTagName(node.name) ?? "")) hasLabel = true;
      },
      JSXAttribute(node) {
        if (node.name.type === "JSXIdentifier" && node.name.name === "aria-label") hasLabel = true;
      },
      "Program:exit"(node) {
        if (!hasLabel) context.report({ node, messageId: "missing" });
      },
    };
  },
};
import { getAttribute, getTagName, hasElementChildren } from "../jsx.mjs";

export default {
  meta: {
    type: "problem",
    docs: { description: "表示を JSX で組み立てる ListBox.Item には textValue を付ける" },
    schema: [],
    messages: { missingTextValue: "textValueのない複合ListBox.Item" },
